  ('6c99e990-32bc-4b88-86f8-171073c0d467', 'f2a3b4c5-6d7e-4f18-9a78-8b9c0d1e2f98', null, 'topic'::public.curated_course_node_type, 'The Investigative Mindset', 'Investigative reporting begins with a disciplined habit of suspicion, curiosity, fairness, and evidence. Students learn to move from vague concern to testable accountability questions.', 0),
  ('433e5fc9-0a90-4cd6-91a7-8325b8ad574f', 'f2a3b4c5-6d7e-4f18-9a78-8b9c0d1e2f98', '6c99e990-32bc-4b88-86f8-171073c0d467', 'subtopic'::public.curated_course_node_type, 'Accountability questions', 'Students learn to identify abuses of power, failures of systems, hidden harms, and claims that can be tested with evidence.', 0),
