  ('51f64713-0faf-4bdf-9fa3-7e222cedb1ab', 'f2a3b4c5-6d7e-4f18-9a78-8b9c0d1e2f98', '01b1d263-7aae-46d9-b165-47da6102437d', 'concept'::public.curated_course_node_type, 'documentation of decisions', null, 2),
