  ('67b7b9ef-bd65-4106-bee6-ee4e35fddb27', 'f2a3b4c5-6d7e-4f18-9a78-8b9c0d1e2f98', '5aaca11c-6280-4f20-916c-f3b053addab7', 'concept'::public.curated_course_node_type, 'tips, audits, lawsuits, inspections, and agendas', null, 0),
