  ('14ae2cbd-0edf-47a5-bac4-68bda4bf4ff5', 'f2a3b4c5-6d7e-4f18-9a78-8b9c0d1e2f98', '5aaca11c-6280-4f20-916c-f3b053addab7', 'concept'::public.curated_course_node_type, 'community harm mapping', null, 2),
