  ('e831ab3a-21a3-4345-b58f-bc4e570c8a98', 'f2a3b4c5-6d7e-4f18-9a78-8b9c0d1e2f98', '81726f7d-9e23-40b9-9720-722ae58fb14d', 'concept'::public.curated_course_node_type, 'source ladders', null, 1),
  ('79647094-1635-45a3-bf7d-f93cf11dec2a', 'f2a3b4c5-6d7e-4f18-9a78-8b9c0d1e2f98', '81726f7d-9e23-40b9-9720-722ae58fb14d', 'concept'::public.curated_course_node_type, 'timeline and task boards', null, 2),
