  ('20972691-9323-4207-a50e-95c1adc6fde5', 'f2a3b4c5-6d7e-4f18-9a78-8b9c0d1e2f98', null, 'topic'::public.curated_course_node_type, 'Confidential Sources', 'Confidential sources can expose serious wrongdoing, but they also create ethical, legal, security, and credibility challenges. Students learn careful source protection and corroboration.', 5),
