  ('6e8729cd-bd6d-4dbb-894a-c3188a1d061c', 'f2a3b4c5-6d7e-4f18-9a78-8b9c0d1e2f98', '251569fc-ebb5-4a82-92d5-2a485993c7ba', 'concept'::public.curated_course_node_type, 'motive and access assessment', null, 0),
  ('b05a3af3-58dd-434b-a66e-0f7319dd85dd', 'f2a3b4c5-6d7e-4f18-9a78-8b9c0d1e2f98', '251569fc-ebb5-4a82-92d5-2a485993c7ba', 'concept'::public.curated_course_node_type, 'risk of retaliation', null, 1),
  ('6a7df86f-3cd3-45c0-ae20-144b62b5c678', 'f2a3b4c5-6d7e-4f18-9a78-8b9c0d1e2f98', '251569fc-ebb5-4a82-92d5-2a485993c7ba', 'concept'::public.curated_course_node_type, 'editor approval and terms of agreement', null, 2),
  ('5409f79f-36ca-40d4-b471-12cd28c9b3d5', 'f2a3b4c5-6d7e-4f18-9a78-8b9c0d1e2f98', '20972691-9323-4207-a50e-95c1adc6fde5', 'subtopic'::public.curated_course_node_type, 'Secure communication', 'Students learn practical source-protection habits for sensitive reporting.', 1),
  ('ab998825-aca9-4093-870b-74f7ebf7fa2f', 'f2a3b4c5-6d7e-4f18-9a78-8b9c0d1e2f98', '5409f79f-36ca-40d4-b471-12cd28c9b3d5', 'concept'::public.curated_course_node_type, 'Signal, encrypted email, and secure dropboxes', null, 0),
  ('976d7c7f-027c-411f-89d9-93a9a1b04a5f', 'f2a3b4c5-6d7e-4f18-9a78-8b9c0d1e2f98', '5409f79f-36ca-40d4-b471-12cd28c9b3d5', 'concept'::public.curated_course_node_type, 'metadata and device hygiene', null, 1),
  ('d2e6fa0d-0951-4021-9641-fe1caea86bd9', 'f2a3b4c5-6d7e-4f18-9a78-8b9c0d1e2f98', '5409f79f-36ca-40d4-b471-12cd28c9b3d5', 'concept'::public.curated_course_node_type, 'meeting and note safety', null, 2),
  ('9b216e37-b2ff-462f-8d51-486f37c1c4fb', 'f2a3b4c5-6d7e-4f18-9a78-8b9c0d1e2f98', '20972691-9323-4207-a50e-95c1adc6fde5', 'subtopic'::public.curated_course_node_type, 'Corroborating confidential claims', 'Students practice building evidence beyond any single unnamed source.', 2),
  ('034ea3da-483b-40ee-9ec9-1e68dc842241', 'f2a3b4c5-6d7e-4f18-9a78-8b9c0d1e2f98', '9b216e37-b2ff-462f-8d51-486f37c1c4fb', 'concept'::public.curated_course_node_type, 'documents, data, and named sources', null, 0),
  ('cc69d811-1b65-4c82-be5d-08e37afa8223', 'f2a3b4c5-6d7e-4f18-9a78-8b9c0d1e2f98', '9b216e37-b2ff-462f-8d51-486f37c1c4fb', 'concept'::public.curated_course_node_type, 'on/off/background terms', null, 1),
  ('c2f22140-1394-4040-8087-ab10e6aa430d', 'f2a3b4c5-6d7e-4f18-9a78-8b9c0d1e2f98', '9b216e37-b2ff-462f-8d51-486f37c1c4fb', 'concept'::public.curated_course_node_type, 'source reliability records', null, 2),
  ('1fda021b-f1a7-4c7a-8a78-d5b57ae795cb', 'f2a3b4c5-6d7e-4f18-9a78-8b9c0d1e2f98', null, 'topic'::public.curated_course_node_type, 'Interviewing for Accountability', 'Investigative interviews are not only quote-gathering. They test evidence, establish timelines, invite response, and give subjects a fair chance to answer serious findings.', 6),
  ('8381719d-1fad-46dc-98a3-4d2bde745422', 'f2a3b4c5-6d7e-4f18-9a78-8b9c0d1e2f98', '1fda021b-f1a7-4c7a-8a78-d5b57ae795cb', 'subtopic'::public.curated_course_node_type, 'Source interviews', 'Students develop trust, preparation habits, and questioning strategies for witnesses, experts, affected people, and insiders.', 0);
