  ('3230126d-2b16-420b-bfef-075b77e0a1f3', 'f2a3b4c5-6d7e-4f18-9a78-8b9c0d1e2f98', '476b7562-b3f6-4832-bfe9-542ea6bd56cf', 'concept'::public.curated_course_node_type, 'conflicts of interest', null, 1),
