update public.learning_paths
set
  title = 'Investigative Reporting',
  goal = 'Investigative Reporting',
  summary = 'Students develop, report, verify, write, and present an accountability investigation grounded in documents, data, interviews, public records, and ethical source work.',
  data = $invrjson${"slug": "investigative-reporting", "title": "Investigative Reporting", "description": "Students develop, report, verify, write, and present an accountability investigation grounded in documents, data, interviews, public records, and ethical source work.", "topics": [{"id": "6c99e990-32bc-4b88-86f8-171073c0d467", "type": "topic", "title": "The Investigative Mindset", "description": "Investigative reporting begins with a disciplined habit of suspicion, curiosity, fairness, and evidence. Students learn to move from vague concern to testable accountability questions.", "children": [{"id": "433e5fc9-0a90-4cd6-91a7-8325b8ad574f", "type": "subtopic", "title": "Accountability questions", "children": [{"id": "7fe1f2d5-820b-41bc-bebe-5c37913e778e", "type": "concept", "title": "who benefits and who is harmed"}, {"id": "22450d1b-a027-4dfb-90bd-de65c33e1c73", "type": "concept", "title": "systems versus anecdotes"}, {"id": "1ad3245b-8864-4719-863c-4ecf4e151ae8", "type": "concept", "title": "public interest and newsworthiness"}], "description": "Students learn to identify abuses of power, failures of systems, hidden harms, and claims that can be tested with evidence."}, {"id": "65af03ac-aa4d-425f-b106-33ec5a2bdfa3", "type": "subtopic", "title": "Hypothesis-driven reporting", "children": [{"id": "de7bab67-4fec-40ff-ad09-326c6848fe99", "type": "concept", "title": "story hypotheses"}, {"id": "53b67577-8b7e-46f6-9b3b-606eea833f6a", "type": "concept", "title": "falsification tests"}, {"id": "6ab97c54-ae5c-4f92-950f-c0043225098f", "type": "concept", "title": "assumption logs"}], "description": "Students practice forming, testing, revising, and sometimes abandoning investigative hypotheses."}, {"id": "01b1d263-7aae-46d9-b165-47da6102437d", "type": "subtopic", "title": "Investigative discipline", "children": [{"id": "daa2fa29-e737-454a-aea4-64e22b9b9153", "type": "concept", "title": "skepticism without cynicism"}, {"id": "b8a621a6-1b8a-497d-bd32-da97890e8fab", "type": "concept", "title": "patience and pattern recognition"}, {"id": "51f64713-0faf-4bdf-9fa3-7e222cedb1ab", "type": "concept", "title": "documentation of decisions"}], "description": "Students build habits that keep ambitious projects accurate, fair, and manageable."}]}, {"id": "6e70bd37-af9d-4a58-a162-7f5d9ba3cec6", "type": "topic", "title": "Developing Investigative Leads", "description": "Strong investigations often start with small anomalies: a tip, a spreadsheet, a lawsuit, a budget line, a pattern of complaints, or a source who knows where to look.", "children": [{"id": "5aaca11c-6280-4f20-916c-f3b053addab7", "type": "subtopic", "title": "Lead generation", "children": [{"id": "67b7b9ef-bd65-4106-bee6-ee4e35fddb27", "type": "concept", "title": "tips, audits, lawsuits, inspections, and agendas"}, {"id": "f7fb1c14-ec23-4d40-ab41-95d0275c5ec8", "type": "concept", "title": "whistleblower signals"}, {"id": "14ae2cbd-0edf-47a5-bac4-68bda4bf4ff5", "type": "concept", "title": "community harm mapping"}], "description": "Students learn systematic ways to find story leads beyond press releases and daily-news assignments."}, {"id": "fe4ed9a3-17bb-4b26-89e7-6985aedf619b", "type": "subtopic", "title": "Scoping and feasibility", "children": [{"id": "581c5e99-f682-4ca0-a0c4-98598d9babfb", "type": "concept", "title": "minimum story test"}, {"id": "9b75a041-c676-4a83-95d5-5f461a58732d", "type": "concept", "title": "records availability"}, {"id": "f947edb9-0100-487e-a21b-5d18a28951c7", "type": "concept", "title": "risk and resource assessment"}], "description": "Students evaluate whether a lead can become a publishable investigation within time, access, and evidence constraints."}, {"id": "81726f7d-9e23-40b9-9720-722ae58fb14d", "type": "subtopic", "title": "Project planning", "children": [{"id": "51382b38-bec8-498b-8dbc-dc18b58c5323", "type": "concept", "title": "reporting memos"}, {"id": "e831ab3a-21a3-4345-b58f-bc4e570c8a98", "type": "concept", "title": "source ladders"}, {"id": "79647094-1635-45a3-bf7d-f93cf11dec2a", "type": "concept", "title": "timeline and task boards"}], "description": "Students translate a lead into a reporting plan with milestones, source maps, records targets, and verification checkpoints."}]}, {"id": "a77e6332-32c3-40ff-937e-9792dfef1442", "type": "topic", "title": "Document-Based Reporting", "description": "Documents are the backbone of many investigations because they preserve claims, decisions, money flows, timelines, and contradictions that interviews alone may miss.", "children": [{"id": "4babcbdd-4ee3-4ffb-b304-fc0dc1d313a8", "type": "subtopic", "title": "Document discovery", "children": [{"id": "984d1cc0-f4a9-4e93-a28c-f2711be25778", "type": "concept", "title": "court files, contracts, budgets, audits, filings, and inspections"}, {"id": "e6df19dc-d553-4a74-8bad-65a54075bcfc", "type": "concept", "title": "meeting minutes and correspondence"}, {"id": "84852b7d-f440-4488-b66b-a2f66001a221", "type": "concept", "title": "archival and regulatory records"}], "description": "Students learn where to find records and how to read them for story value."}, {"id": "16d0cea1-a6ef-405d-8819-b1f89ac9efd7", "type": "subtopic", "title": "Document analysis", "children": [{"id": "5c39a35a-7d21-4c18-b9c3-299f58654920", "type": "concept", "title": "annotation workflows"}, {"id": "f74d0375-b7ec-4bb4-aa2b-0177f1b9f6e0", "type": "concept", "title": "chronologies"}, {"id": "122013f9-edfa-4bb4-8d5a-ca79a6081b42", "type": "concept", "title": "document comparison and version tracking"}], "description": "Students practice extracting facts, timelines, names, contradictions, and missing pieces from dense records."}, {"id": "918699d1-460e-41cf-95d6-3da61df76c92", "type": "subtopic", "title": "Document verification", "children": [{"id": "9a265dee-9a27-48a7-91b9-f1d723c73af9", "type": "concept", "title": "chain of custody"}, {"id": "8799a6d7-a710-4bad-8ef8-3550e1443f6f", "type": "concept", "title": "redactions and omissions"}, {"id": "32347b8a-869a-4c3f-8618-acae183a3a6f", "type": "concept", "title": "corroboration with people and data"}], "description": "Students evaluate authenticity, completeness, context, and provenance before relying on records."}]}, {"id": "977ea504-802f-4dc9-945b-392427498903", "type": "topic", "title": "Public Records Investigations", "description": "Public records law lets reporters inspect government activity, but effective records work requires strategy, persistence, precision, and appeal skills.", "children": [{"id": "8599cd43-00f1-4cd1-85ee-1adbe0085003", "type": "subtopic", "title": "Records law fundamentals", "children": [{"id": "259a9b9e-6df0-4df3-92a9-cdfecf8a8cbc", "type": "concept", "title": "FOIA and state public records laws"}, {"id": "13465a67-c521-434b-ac14-096967073a74", "type": "concept", "title": "open meetings and agendas"}, {"id": "60cb4f85-0fcc-4f26-ad71-64b829b0f1a1", "type": "concept", "title": "common exemptions and delays"}], "description": "Students learn the logic of open-records and open-meetings laws and how exemptions shape access."}, {"id": "c56adfca-4725-4c99-bd7d-305b1882f068", "type": "subtopic", "title": "Request strategy", "children": [{"id": "1afe2284-9e95-4087-98de-2be4bc64bf61", "type": "concept", "title": "request wording"}, {"id": "2cd44df0-66a5-4d21-8dba-e8e99e665188", "type": "concept", "title": "fee waivers and narrowing"}, {"id": "8cbd35ec-a2a0-4570-97fc-e0a581d0edfa", "type": "concept", "title": "appeals and negotiation"}], "description": "Students practice drafting narrow, effective requests and tracking responses professionally."}, {"id": "0ce176c3-861f-4a2e-b3a0-002d91a2da1a", "type": "subtopic", "title": "Records-driven reporting", "children": [{"id": "ea3506c1-3d9c-4962-b75f-d3b70678af38", "type": "concept", "title": "records logs"}, {"id": "fb2d0f79-19af-4655-a576-724dfaef32f6", "type": "concept", "title": "follow-up requests"}, {"id": "acb4b678-aa55-43dc-9870-0c98cf21a60a", "type": "concept", "title": "document-backed interview questions"}], "description": "Students use records to build stories, identify sources, and test official narratives."}]}, {"id": "0ec932f5-be67-43c5-b246-3965c62c5e54", "type": "topic", "title": "Data and Investigations", "description": "Data can reveal patterns no single source can see. Students learn to acquire, clean, analyze, verify, and explain data as evidence rather than decoration.", "children": [{"id": "4ce649c6-95b1-49f9-842d-9fc56d62ff33", "type": "subtopic", "title": "Finding and acquiring data", "children": [{"id": "767e80b3-4df4-4874-9922-73344707c804", "type": "concept", "title": "public data portals"}, {"id": "a2696063-4522-40e1-8b35-5a112aa698be", "type": "concept", "title": "structured versus messy records"}, {"id": "3f7a68bf-1c81-42a2-b59c-fbe68b840dc2", "type": "concept", "title": "data dictionaries and methodology notes"}], "description": "Students identify datasets from agencies, courts, regulators, scraping, leaks, and manual collection."}, {"id": "677e6159-a342-4cda-8257-bc620ba54fd1", "type": "subtopic", "title": "Cleaning and analysis", "children": [{"id": "93c28103-7492-48ae-a76e-fba007e5c688", "type": "concept", "title": "cleaning logs"}, {"id": "ebcf17ee-b872-4af9-abde-8f8980efbe15", "type": "concept", "title": "joins, filters, pivots, and summary statistics"}, {"id": "c94dc49c-5ba4-4e1b-b553-374767130911", "type": "concept", "title": "outlier and missing-data checks"}], "description": "Students practice reproducible spreadsheet and basic data workflows appropriate for journalism."}, {"id": "a8b73e02-467f-4da6-8062-1dc45b030bea", "type": "subtopic", "title": "Data verification and fairness", "children": [{"id": "7b3a3e1c-ed5b-4b74-9ec3-8499ffb6f6cd", "type": "concept", "title": "source documentation"}, {"id": "1ed7eee0-be05-4aa5-b1cb-ec042f62aa91", "type": "concept", "title": "replication and peer review"}, {"id": "716b3c78-5271-4f2e-b954-8d98426f2198", "type": "concept", "title": "bias, coverage gaps, and denominator problems"}], "description": "Students learn to test data quality, avoid overclaiming, and explain limits transparently."}]}, {"id": "20972691-9323-4207-a50e-95c1adc6fde5", "type": "topic", "title": "Confidential Sources", "description": "Confidential sources can expose serious wrongdoing, but they also create ethical, legal, security, and credibility challenges. Students learn careful source protection and corroboration.", "children": [{"id": "251569fc-ebb5-4a82-92d5-2a485993c7ba", "type": "subtopic", "title": "When confidentiality is justified", "children": [{"id": "6e8729cd-bd6d-4dbb-894a-c3188a1d061c", "type": "concept", "title": "motive and access assessment"}, {"id": "b05a3af3-58dd-434b-a66e-0f7319dd85dd", "type": "concept", "title": "risk of retaliation"}, {"id": "6a7df86f-3cd3-45c0-ae20-144b62b5c678", "type": "concept", "title": "editor approval and terms of agreement"}], "description": "Students evaluate when anonymity serves public interest and when it weakens accountability."}, {"id": "5409f79f-36ca-40d4-b471-12cd28c9b3d5", "type": "subtopic", "title": "Secure communication", "children": [{"id": "ab998825-aca9-4093-870b-74f7ebf7fa2f", "type": "concept", "title": "Signal, encrypted email, and secure dropboxes"}, {"id": "976d7c7f-027c-411f-89d9-93a9a1b04a5f", "type": "concept", "title": "metadata and device hygiene"}, {"id": "d2e6fa0d-0951-4021-9641-fe1caea86bd9", "type": "concept", "title": "meeting and note safety"}], "description": "Students learn practical source-protection habits for sensitive reporting."}, {"id": "9b216e37-b2ff-462f-8d51-486f37c1c4fb", "type": "subtopic", "title": "Corroborating confidential claims", "children": [{"id": "034ea3da-483b-40ee-9ec9-1e68dc842241", "type": "concept", "title": "documents, data, and named sources"}, {"id": "cc69d811-1b65-4c82-be5d-08e37afa8223", "type": "concept", "title": "on/off/background terms"}, {"id": "c2f22140-1394-4040-8087-ab10e6aa430d", "type": "concept", "title": "source reliability records"}], "description": "Students practice building evidence beyond any single unnamed source."}]}, {"id": "1fda021b-f1a7-4c7a-8a78-d5b57ae795cb", "type": "topic", "title": "Interviewing for Accountability", "description": "Investigative interviews are not only quote-gathering. They test evidence, establish timelines, invite response, and give subjects a fair chance to answer serious findings.", "children": [{"id": "8381719d-1fad-46dc-98a3-4d2bde745422", "type": "subtopic", "title": "Source interviews", "children": [{"id": "d81ffe94-1307-48a4-890a-b00d7b3e3666", "type": "concept", "title": "pre-interview research"}, {"id": "a435cc84-45ab-46f9-a180-b6028ffa77c4", "type": "concept", "title": "open-ended and precise questions"}, {"id": "1a07bdd8-8d49-4111-b0eb-ccc50d9a3d65", "type": "concept", "title": "trauma-informed listening"}], "description": "Students develop trust, preparation habits, and questioning strategies for witnesses, experts, affected people, and insiders."}, {"id": "81776023-e212-4526-898e-73bcdf147b9a", "type": "subtopic", "title": "Confrontational and accountability interviews", "children": [{"id": "f7e36759-20bc-4fad-8deb-13e0eededa56", "type": "concept", "title": "right-of-reply protocols"}, {"id": "1881d9c1-9bb3-43be-a8e5-ca260f1a99a2", "type": "concept", "title": "evidence sequencing"}, {"id": "29ea04e8-e8f3-4375-b6b4-9abc00bd5cbf", "type": "concept", "title": "recording and note verification"}], "description": "Students learn to present findings fairly, ask direct questions, and handle evasion or denial."}, {"id": "50d5153d-a6b1-4baf-964c-4f5dbca22483", "type": "subtopic", "title": "Interview ethics", "children": [{"id": "3da7bd44-ab86-44ef-90b5-6f021d7c9658", "type": "concept", "title": "informed consent limits"}, {"id": "6cb91f7e-5f53-4ef8-94a3-b9a91d0e0158", "type": "concept", "title": "vulnerable sources"}, {"id": "90348791-b837-4483-8654-ae2c3fe759c9", "type": "concept", "title": "quote accuracy and context"}], "description": "Students consider power, consent, harm, identity, and representation in high-stakes reporting relationships."}]}, {"id": "a7d01bff-bf14-4318-9cb2-10b2ac462393", "type": "topic", "title": "Building an Evidence File", "description": "A publishable investigation needs an organized evidentiary foundation. Students learn to maintain files that editors, lawyers, and collaborators can inspect and trust.", "children": [{"id": "c7598e88-b88f-4fa8-8af8-a74fd106222f", "type": "subtopic", "title": "Evidence organization", "children": [{"id": "e73da786-cee5-4a05-ae1e-2c96167a9805", "type": "concept", "title": "file naming and folders"}, {"id": "576836aa-4bbb-4e0a-a8ca-65407d8a4f80", "type": "concept", "title": "source and document indexes"}, {"id": "e8cb2354-1ba8-4106-9af3-59840030852e", "type": "concept", "title": "timeline databases"}], "description": "Students build a searchable structure for documents, interviews, data, media, and notes."}, {"id": "29d36eb9-cab1-4a4a-b1cb-3178fed91171", "type": "subtopic", "title": "Fact-checking systems", "children": [{"id": "3d4939da-de38-4e0f-a96f-af97c9a49ac1", "type": "concept", "title": "claim checklists"}, {"id": "8e904bcf-2b00-4433-8e2e-f44317cf7beb", "type": "concept", "title": "citation packets"}, {"id": "dd4be2bf-a70c-4e6e-869a-79f48f1f31b3", "type": "concept", "title": "quote and number verification"}], "description": "Students learn line-by-line support practices for every factual claim in a major investigation."}, {"id": "1d114b1a-3684-4df2-bb85-5ec7ccd43969", "type": "subtopic", "title": "Editorial review readiness", "children": [{"id": "f2f31c68-5061-4d9d-8e67-745cb899976e", "type": "concept", "title": "evidence memos"}, {"id": "07358bd3-ad32-4ab8-bfe8-6fc8b1d77225", "type": "concept", "title": "response tracking"}, {"id": "6563ef0e-3b01-4cb6-bea8-cd3ce0be6a38", "type": "concept", "title": "uncertainty and caveat notes"}], "description": "Students prepare materials for editors, legal review, and pre-publication challenge."}]}, {"id": "0acb3781-920e-4b3a-a721-aee10f888eef", "type": "topic", "title": "Legal and Ethical Issues", "description": "Investigations carry heightened legal and ethical stakes. Students learn to reduce avoidable risk while preserving the watchdog role of journalism.", "children": [{"id": "6606cbe0-8389-46de-9217-9364201a1b82", "type": "subtopic", "title": "Defamation, privacy, and newsgathering risk", "children": [{"id": "363d5013-d727-40a1-b449-10883a7c7c5c", "type": "concept", "title": "libel and actual malice"}, {"id": "cdd922d2-f43a-47e2-87ab-ac54f8cc26fb", "type": "concept", "title": "privacy and intrusion"}, {"id": "169c0fc5-9888-4203-b980-fafc5ce79e20", "type": "concept", "title": "recording, trespass, and misrepresentation"}], "description": "Students review legal concepts most relevant to investigative work."}, {"id": "af04fee7-763f-45ec-9b45-a939dc5d2038", "type": "subtopic", "title": "Fairness and right of reply", "children": [{"id": "b4f6d8ad-f80a-4881-bda6-73a093ee5b4f", "type": "concept", "title": "no-surprises letters"}, {"id": "5683b6e0-144b-495a-aa98-b88a725ee0c3", "type": "concept", "title": "subject response deadlines"}, {"id": "725502e2-ef00-4900-92c9-4f1e94593820", "type": "concept", "title": "including denials and context"}], "description": "Students learn procedures that make difficult stories more accurate and more defensible."}, {"id": "476b7562-b3f6-4832-bfe9-542ea6bd56cf", "type": "subtopic", "title": "Ethical decision-making", "children": [{"id": "105a1962-04c8-4d9f-8a69-abd2cb01aae9", "type": "concept", "title": "undercover reporting thresholds"}, {"id": "3230126d-2b16-420b-bfef-075b77e0a1f3", "type": "concept", "title": "conflicts of interest"}, {"id": "d1c4c705-c76e-4654-8015-ac246e836816", "type": "concept", "title": "minimizing harm without burying truth"}], "description": "Students weigh public interest, harm, independence, deception, source motives, and proportionality."}]}, {"id": "18313f49-9a59-48b3-bfba-02b4af1a3816", "type": "topic", "title": "Writing and Presenting the Investigation", "description": "Investigative writing must make complex evidence understandable, compelling, fair, and precise. Students learn to turn reporting files into narrative, explanatory, and multimedia packages.", "children": [{"id": "3bb1f01e-6420-48be-b52a-f69e23a7ac04", "type": "subtopic", "title": "Story structure", "children": [{"id": "7a867ab3-a46e-46d1-b667-f39a9f6dc48d", "type": "concept", "title": "nut graf and findings summary"}, {"id": "6d540fdc-897d-4920-b41a-31bd1ee509ab", "type": "concept", "title": "chronological, thematic, and case-study structures"}, {"id": "2512523b-85f9-492e-99f6-0dc6283fb1ca", "type": "concept", "title": "scene-evidence-explanation rhythm"}], "description": "Students choose structures that reveal findings clearly and sustain reader attention."}, {"id": "e2cbae76-1fc9-4b47-9adc-067b9e3cb317", "type": "subtopic", "title": "Evidence-rich prose", "children": [{"id": "160dcefb-ee61-43ca-ac01-ae65ac53b021", "type": "concept", "title": "showing proof without dumping documents"}, {"id": "35992bd6-d0b4-4db4-b297-ee7afeccc7aa", "type": "concept", "title": "precision in allegations"}, {"id": "f0b52363-0236-4160-b6b8-bba370ae2037", "type": "concept", "title": "explaining methods and limits"}], "description": "Students learn to write with documentation, attribution, caveats, and clarity."}, {"id": "1428d06f-c7a1-4239-8224-d27fe091919b", "type": "subtopic", "title": "Presentation and impact", "children": [{"id": "b6975299-edcf-4a8a-a838-94c99cb67676", "type": "concept", "title": "document embeds and annotations"}, {"id": "1e9b58eb-7c39-40d3-99bb-4c8367bec787", "type": "concept", "title": "graphics and timelines"}, {"id": "3ee727bc-aeed-4428-afbb-743f51ecce6c", "type": "concept", "title": "impact tracking and corrections"}], "description": "Students design publication packages that include visuals, data, documents, engagement, and follow-up plans."}]}, {"id": "45acc557-34c7-4e30-b4ef-a9af7b87f0dc", "type": "topic", "title": "Source Protection, Digital Security, Trauma-Informed Reporting, and Publication Risk", "description": "Investigative work protects people, information, and public trust. This capstone unit integrates safety, security, wellbeing, and publication-risk planning.", "children": [{"id": "127dc8ec-2c91-45ed-90a6-e256733c0fec", "type": "subtopic", "title": "Digital and operational security", "children": [{"id": "47323618-27a0-429e-a09d-c81ac57a66ed", "type": "concept", "title": "risk assessment"}, {"id": "6fad80a3-0d41-4daf-ad3b-d712fb24ae8b", "type": "concept", "title": "password managers, encryption, and backups"}, {"id": "959bb8e9-ca64-47f1-b4c0-abbdc22a64b5", "type": "concept", "title": "phishing, doxxing, and harassment response"}], "description": "Students apply threat modeling to sources, reporters, files, communications, and publication workflows."}, {"id": "75784422-9150-4ab0-a2e2-53ca91eb367c", "type": "subtopic", "title": "Trauma-informed investigative practice", "children": [{"id": "cdd2f4c0-65da-476c-a319-ae4b903f4c1c", "type": "concept", "title": "choice, control, and consent"}, {"id": "4165ba2f-4c65-4978-a71a-71101d16af3d", "type": "concept", "title": "interview pacing and follow-up"}, {"id": "0522e1c6-4054-41bf-9154-18490a67f62d", "type": "concept", "title": "vicarious trauma and support plans"}], "description": "Students learn to report on harm without exploiting sources or ignoring reporter wellbeing."}, {"id": "e4747ef9-6fcf-46b2-8b3b-33c4ac5cdbd9", "type": "subtopic", "title": "Publication risk and collaboration", "children": [{"id": "6f52e9ea-537b-4714-8430-4786020df87d", "type": "concept", "title": "pre-publication review"}, {"id": "8201ac38-f61f-4922-a765-7d4c51bcf69d", "type": "concept", "title": "cross-newsroom collaboration"}, {"id": "b9a4bac7-9d96-4afb-9f5c-bf11db4dfc2f", "type": "concept", "title": "post-publication response and impact monitoring"}], "description": "Students prepare for legal, institutional, political, and safety pressures before and after publication."}]}], "dbBacked": true}$invrjson$::jsonb,
